/* The Interactive Classroom: Grade 2 Social Studies — Units 11–24: our world, the globe, climates, countries, Canada, travel, needs, homes, clothes, sports, food, where people live, adapting and resources */
(function(){
"use strict";
const P=window.PM;if(!P||!P.unit)return;const U=P.unit,R=P.R,S=P.S;
const G=(items)=>({grid:{rows:3,cols:5,items}});

/* 11 ─ Our world: continents, oceans, compass */
U({id:'o11',title:'Our world',strand:'Global Communities',codes:['B2','B3'],
 guide:{goal:'Name the seven continents and five oceans, and use a compass rose (north, east, south, west) to describe where places are.',words:'continent, ocean, compass rose, north, south, east, west, map, globe',ask:['How many continents are there?','Which continent is Canada on?','Which direction is up on most maps?'],home:'Use a compass app or the sun to find north from your front door.'},
 watch:['Seven continents!','North America, South America, Europe, Africa, Asia, Australia and Antarctica.'],
 fig:'A world map with the continents and a compass rose.',
 page:{story:{title:'Around the World in a Day',text:'In Ms. Rossi’s class, the *world map* covered a whole wall. "There are *seven continents*," she said: *North America*, *South America*, *Europe*, *Africa*, *Asia*, *Australia* and *Antarctica*. "*Asia* is the biggest. We live in *North America*." She pointed to the *compass rose* in the corner. "N means *north*, S means *south*, E means *east* and W means *west*. Europe is *east* of North America, across the Atlantic Ocean!"',pics:['globe','map','compass','canada']},
  boxes:[{title:'Seven continents',lines:['North America','South America','Europe','Africa','Asia (the biggest)','Australia','Antarctica']},
   {title:'Compass rose',text:'A *compass rose* shows directions on a map: *north* (up), *south* (down), *east* (right) and *west* (left).',lines:['North America is *north* of South America','Europe is *east* of North America']}],
  cards:[{q:'Kangaroos live in…',pics:['kangaroo'],a:'*Australia*'},{q:'Between South America and Africa is…',a:'the *Atlantic Ocean*'}],
  words:[['continent','one of the seven big pieces of land on Earth'],['compass rose','a symbol on a map that shows directions']]},
 steps:[
  {say:'Read the story',speech:'There are seven continents: North America, South America, Europe, Africa, Asia, Australia and Antarctica. Asia is the biggest. We live in North America. The compass rose shows north, south, east and west.',set:G({A1:'canada',C2:'parrot',A3:'castle',B3:'lion',A4:'panda',C5:'kangaroo'}),
   cues:[['North America','canada','North America'],['South America','parrot','South America'],['Africa','lion','Africa'],['Asia','panda','Asia'],['Australia','kangaroo','Australia']]},
  {say:'Compass rose',speech:'On most maps, north is at the top. South is at the bottom. East is to the right, and west is to the left.',set:S.row(['compass'],{labels:['N E S W']}),
   cues:[['north is at the top','compass','N ↑']]},
  {say:'Oceans',speech:'Big oceans surround the continents: the Pacific, the Atlantic, the Indian, the Arctic and the Southern Ocean.',set:S.row(['ocean','whale','fish'],{labels:['Pacific','Atlantic','Arctic']}),
   cues:[['the Pacific','ocean','Pacific'],['the Atlantic','whale','Atlantic']]},
  {say:'Which direction?',speech:'North America is north of South America. Europe is east of North America. Use the compass rose to find out!',set:G({A1:'canada',C1:'parrot',A3:'castle'}),
   cues:[['north of South America','canada','north'],['east of North America','castle','east']]}],
 more:{title:'Did you know?',text:'*Antarctica* is the coldest, windiest continent. Almost no people live there all year, but scientists visit to study ice, weather and penguins. The ice there is up to 4 kilometres thick!',pics:['penguin','ice','snowflake','globe'],lead:'A world fact!'},
 rounds:[R.q('How many continents are there?',['7','5','10'],'7'),R.q('Which continent is Canada on?',['North America','Europe','Asia'],'North America',{set:{row:['canada'],keep:true}}),
  R.q('Which continent is the biggest?',['Asia','Australia','Europe'],'Asia'),R.q('Kangaroos live in…',['Australia','Antarctica','Europe'],'Australia',{set:{row:['kangaroo'],keep:true}}),
  R.q('On most maps, north is…',['at the top','at the bottom','on the right'],'at the top'),R.q('What does a compass rose show?',['directions','temperature','time'],'directions'),
  R.q('North America is ___ of South America.',['north','south','east'],'north'),R.q('Europe is ___ of North America.',['east','west','south'],'east'),
  R.grid('Tap the continent with the kangaroo.',{rows:3,cols:5,items:{A1:'canada',C5:'kangaroo',B3:'lion'}},'C5'),R.q('Between South America and Africa is the…',['Atlantic Ocean','Pacific Ocean','Arctic Ocean'],'Atlantic Ocean'),
  R.q('In "Did you know?", which is the coldest continent?',['Antarctica','Africa','Asia'],'Antarctica'),R.tf('E on a compass rose means east.',true)],
 tries:[['Name three continents.','*North America*, *Asia*, *Africa*…'],['Which way is the sun in the morning?','in the *east*']]});

/* 12 ─ The globe */
U({id:'o12',title:'The globe',strand:'Global Communities',codes:['B2','B3'],
 guide:{goal:'Use a globe to find the Equator, the Northern and Southern Hemispheres and the North and South Poles, and describe how places near them are different.',words:'globe, Equator, hemisphere, North Pole, South Pole, rainforest',ask:['What is the Equator?','Which hemisphere is Canada in?','Why is it warm near the Equator?'],home:'Spin a globe (or an online globe). Find Canada, the Equator and both poles.'},
 watch:['Spin the Earth!','The Equator is an imaginary line around the middle of the Earth.'],
 fig:'A spinning globe with the Equator and the poles.',
 page:{story:{title:'Mina Spins the Globe',text:'Mina spun the classroom *globe*. "A globe is a *model of the Earth*," said her teacher. "See the dotted line around the middle? That is the *Equator*. It is an imaginary line halfway between the *North Pole* and the *South Pole*." Above it is the *Northern Hemisphere*, where Canada is. Below it is the *Southern Hemisphere*, with Chile and Australia. Near the Equator, it is warm and rainy, with huge *rainforests*. Near the poles, it is icy cold.',pics:['globe','sun','polar bear','penguin']},
  boxes:[{title:'Parts of the globe',lines:['*Equator*: imaginary line around the middle','*Northern Hemisphere*: top half','*Southern Hemisphere*: bottom half','*North Pole*: the very top','*South Pole*: the very bottom']},
   {title:'Different places',ex:[['sun','Equator: *warm*, rain'],['tree','largest *rainforests*'],['polar bear','North Pole: *ice*, polar bears'],['penguin','South Pole: cold *desert*, penguins']]}],
  cards:[{q:'Which hemisphere is Canada in?',a:'the *Northern* Hemisphere'},{q:'A country on the Equator?',a:'*Brazil*, *Ecuador*, *Kenya*…'}],
  words:[['Equator','an imaginary line around the middle of the Earth'],['hemisphere','half of the Earth']]},
 steps:[
  {say:'Read the story',speech:'A globe is a model of the Earth. The dotted line around the middle is the Equator, halfway between the North Pole and the South Pole. Canada is in the Northern Hemisphere. Near the Equator it is warm and rainy. Near the poles it is icy cold.',set:{custom:'globe',time:'day'},
   cues:[['A globe','child','Earth'],['the Equator','sun','Equator']]},
  {say:'Hemispheres',speech:'The Equator cuts the Earth in half. The top half is the Northern Hemisphere. The bottom half is the Southern Hemisphere.',set:S.row(['canada','kangaroo'],{labels:['Northern','Southern']}),
   cues:[['Northern Hemisphere','canada','Canada'],['Southern Hemisphere','kangaroo','Australia']]},
  {say:'Near the Equator',speech:'Places near the Equator get the most sunlight. They are very warm with lots of rain, and home to the biggest tropical rainforests.',set:S.row(['sun','rain','tree'],{labels:['most sunlight','lots of rain','rainforest']}),
   cues:[['the most sunlight','sun','sun'],['lots of rain','rain','rain'],['rainforests','tree','rainforest']]},
  {say:'At the poles',speech:'The North Pole is covered by ice, and polar bears live nearby. The South Pole is a cold desert: it rarely snows! Penguins live in the south.',set:S.row(['polar bear','penguin'],{labels:['North Pole','South Pole']}),
   cues:[['polar bears','polar bear','north'],['Penguins','penguin','south']]}],
 more:{title:'Did you know?',text:'When it is *summer* in Canada, it is *winter* in Australia! The two hemispheres have opposite seasons, so some Australian families eat their holiday dinners on the *beach* in December.',pics:['kangaroo','beach','snowflake','sun'],lead:'A world fact!'},
 rounds:[R.q('What is a globe?',['a model of the Earth','a kind of ball game','a lamp'],'a model of the Earth'),R.q('The imaginary line around the middle of the Earth is the…',['Equator','North Pole','compass'],'Equator'),
  R.q('The top half of the Earth is the…',['Northern Hemisphere','Southern Hemisphere','Equator'],'Northern Hemisphere'),R.q('Which hemisphere is Canada in?',['Northern','Southern'],'Northern',{set:{row:['canada'],keep:true}}),
  R.q('The very bottom of the Earth is the…',['South Pole','North Pole','Equator'],'South Pole'),R.q('Places near the Equator are…',['warm with lots of rain','icy cold','always snowy'],'warm with lots of rain'),
  R.q('Which animal lives near the North Pole?',['polar bear','penguin','kangaroo'],'polar bear',{set:{row:['polar bear','penguin'],keep:true}}),R.q('The South Pole is like a cold…',['desert','rainforest','beach'],'desert'),
  R.q('The largest tropical rainforests are near the…',['Equator','North Pole','South Pole'],'Equator'),R.tf('The Equator is a real painted line on the ground.',false),
  R.q('In "Did you know?", when it is summer in Canada, in Australia it is…',['winter','summer','spring'],'winter'),R.q('Which country is in the Southern Hemisphere?',['Chile','Canada','Iceland'],'Chile')],
 tries:[['Find the Equator on a globe.','the line around the *middle*'],['What is a hemisphere?','*half* of the Earth']]});

/* 13 ─ Climates of North America */
U({id:'o13',title:'Climates of North America',strand:'Global Communities',codes:['B1','B2'],
 guide:{goal:'Describe how places closer to the Equator are warmer and places farther away are colder with more distinct seasons, using Canada, the United States and Mexico.',words:'climate, warmer, colder, season, distinct, Equator',ask:['Which country in North America is the warmest?','Why does Canada have four seasons?','What is climate?'],home:'Compare today’s weather in your town with a city in Mexico online.'},
 watch:['Closer is warmer!','Mexico is closer to the Equator, so it is warmer. Canada is farther, so it is colder.'],
 fig:'North America from cold north to warm south.',
 page:{story:{title:'Three Pen Pals',text:'Leo lives in *Canada*, Jade lives in the *United States* and Diego lives in *Mexico*. In January, Leo wrote, "We built a snow fort! It is −15°C." Jade wrote from Florida, "It is warm and humid here." Diego wrote, "It is hot and dry in my town." Their teacher explained: the *closer* a place is to the *Equator*, the *warmer* it is. The *farther* away, the *colder* it is, and the more *distinct* the seasons are.',pics:['canada','snowman','sun','cactus']},
  boxes:[{title:'North America',lines:['three main countries: *Canada*, the *United States*, *Mexico*','warmest: *Mexico* (closest to the Equator)','coldest: *Canada* (farthest from the Equator)']},
   {title:'Four seasons in Canada',ex:[['seedling','*spring*: planting'],['sun','*summer*: mowing the lawn'],['fallen leaf','*fall*: raking leaves'],['snowman','*winter*: building a snowman']]}],
  cards:[{q:'Closer to the Equator means…',a:'*warmer*'},{q:'Why does Canada have four distinct seasons?',a:'it is *far* from the Equator'}],
  words:[['climate','the usual weather of a place over many years'],['distinct','easy to tell apart']]},
 steps:[
  {say:'Read the story',speech:'Leo in Canada built a snow fort at minus fifteen degrees. Jade in Florida said it was warm. Diego in Mexico said it was hot and dry. The closer a place is to the Equator, the warmer it is.',set:S.row(['canada','sun','cactus'],{labels:['Canada: cold','United States','Mexico: hot']}),
   cues:[['Leo in Canada','canada','cold'],['Jade in Florida','sun','warm'],['Diego in Mexico','cactus','hot']]},
  {say:'Closer, warmer',speech:'Mexico is closest to the Equator, so it is the warmest. Canada is farthest, so it is the coldest.',set:S.order(['cactus','sun','snowman']),
   cues:[['Mexico','cactus','warmest'],['Canada','snowman','coldest','play']]},
  {say:'Four seasons',speech:'Canada is far from the Equator, so it has four distinct seasons: spring, summer, fall and winter.',set:S.order(['seedling','sun','fallen leaf','snowman']),
   cues:[['spring','seedling','spring'],['summer','sun','summer'],['fall','fallen leaf','fall'],['winter','snowman','winter','play']]},
  {say:'Climate',speech:'Climate is the usual weather of a place over many years. Weather can change every day, but climate stays about the same.',set:S.row(['rain','sun','snowflake'],{labels:['weather today','usual weather','climate']}),
   cues:[['Weather can change','rain','weather'],['climate stays','snowflake','climate']]}],
 more:{title:'Did you know?',text:'*Canada* is the second-largest country in the world, so it has many climates! The far north is *arctic*, the west coast is rainy and mild, and the prairies can be very hot in summer and very cold in winter.',pics:['canada','snowflake','rain','sun'],lead:'A Canada fact!'},
 rounds:[R.q('What are the three main countries of North America?',['Canada, the United States, Mexico','Canada, Brazil, Iceland','France, Japan, Kenya'],'Canada, the United States, Mexico'),R.q('Which is the *warmest* country?',['Mexico','Canada','the United States'],'Mexico'),
  R.q('Which is the *coldest* country?',['Canada','Mexico','the United States'],'Canada',{set:{row:['canada'],keep:true}}),R.q('The closer a place is to the Equator, the ___ its climate.',['warmer','colder'],'warmer'),
  R.q('The farther from the Equator, the more distinct the…',['seasons','directions','oceans'],'seasons'),R.order('Put Canada’s seasons in order, starting with spring.',['seedling','sun','fallen leaf','snowman']),
  R.q('Raking leaves happens in…',['fall','summer','spring'],'fall'),R.q('Planting seeds happens in…',['spring','winter','fall'],'spring'),
  R.q('What did Leo build in January?',['a snow fort','a sandcastle','a kite'],'a snow fort'),R.q('What is *climate*?',['the usual weather over many years','today’s weather','a kind of cloud'],'the usual weather over many years'),
  R.q('In "Did you know?", Canada is the ___ largest country.',['second','tenth','smallest'],'second'),R.tf('Canada has four distinct seasons.',true)],
 tries:[['What season is it now?','it is *fall*! (or whatever season it is)'],['Name something you do in winter.','*skate*, *sled*, *build a snowman*']]});

/* 14 ─ Unique countries: Brazil and Iceland */
U({id:'o14',title:'Unique countries',strand:'Global Communities',codes:['B1','B2','B3'],
 guide:{goal:'Compare Brazil (warm, near the Equator, Amazon rainforest, many animals) and Iceland (cold, far north, volcanoes, geysers, glaciers).',words:'Brazil, Amazon, rainforest, Iceland, volcano, geyser, glacier, hot spring, landform',ask:['Why does Brazil have so many animals?','What is a geyser?','Is Iceland hot or cold?'],home:'Find Brazil and Iceland on a map. Which is closer to Canada?'},
 watch:['Hot and cold countries!','Brazil has a giant rainforest. Iceland has volcanoes and glaciers.'],
 fig:'A rainforest country and an icy, fiery island.',
 page:{story:{title:'Postcards from Two Countries',text:'Aunt Rosa sent a postcard from *Brazil*: "Hello from the *Amazon rainforest*! It is warm and rainy, and I saw toucans, monkeys and a sloth. The Amazon River is enormous!" Then Uncle Finn sent one from *Iceland*: "Brrr! It is cold, but I swam in a natural *hot spring*! I saw a *geyser* shoot hot water into the sky, a *volcano* and a huge *glacier*." What different places!',pics:['parrot','monkey','volcano','ice']},
  boxes:[{title:'Brazil',lines:['mostly in the *Southern* Hemisphere','*south* of Canada','lies on the *Equator*','*warm* climate','the *Amazon* River and rainforest','home to thousands of kinds of animals'],cols:2},
   {title:'Iceland',lines:['in the *Northern* Hemisphere','*east* of Canada','*far* from the Equator','*cold* climate','*hot springs*, *geysers*','*volcanoes*, *glaciers*'],cols:2}],
  cards:[{q:'A big spray of hot water from underground is a…',a:'*geyser*'},{q:'A big block of ice that moves very slowly is a…',a:'*glacier*'}],
  words:[['rainforest','a thick forest with lots of rain'],['geyser','a spring that shoots hot water into the air']]},
 steps:[
  {say:'Read the story',speech:'Aunt Rosa wrote from Brazil: the Amazon rainforest is warm and rainy, with toucans and monkeys. Uncle Finn wrote from Iceland: it is cold, but he swam in a hot spring and saw a geyser, a volcano and a glacier.',set:S.row(['parrot','monkey','volcano','ice'],{labels:['toucan','monkey','volcano','glacier']}),
   cues:[['toucans','parrot','Brazil'],['monkeys','monkey','Brazil'],['a volcano','volcano','Iceland'],['a huge glacier','ice','Iceland']]},
  {say:'Brazil',speech:'Brazil lies on the Equator, so it is warm. The Amazon rainforest gets lots of rain, so many plants and animals live there.',set:S.row(['sun','tree','parrot','monkey'],{labels:['warm','rainforest','toucan','monkey']}),
   cues:[['on the Equator','sun','warm'],['Amazon rainforest','tree','Amazon']]},
  {say:'Iceland’s landforms',speech:'Iceland has special landforms. A hot spring is warm water from underground. A geyser sprays hot water into the air. A volcano can shoot out lava. A glacier is a huge, slow block of ice.',set:S.row(['water','volcano','ice'],{labels:['hot spring','volcano','glacier']}),
   cues:[['A hot spring','water','hot spring'],['A volcano','volcano','lava'],['A glacier','ice','glacier']]},
  {say:'Compare',speech:'Brazil is warm and close to the Equator. Iceland is cold and far from the Equator. Both are amazing places!',set:S.sort(['Brazil','Iceland'],[['parrot',0,'toucan'],['volcano',1,'volcano'],['tree',0,'rainforest'],['ice',1,'glacier']]),
   cues:[['Brazil is warm','bin:Brazil','Brazil'],['Iceland is cold','bin:Iceland','Iceland','play']]}],
 more:{title:'Did you know?',text:'Brazil is home to about *1,700 kinds of birds*, more than 400 kinds of mammals and many reptiles and frogs! The warm, wet rainforest has lots of food and places to live, so many animals can survive there.',pics:['parrot','frog','monkey','tree'],lead:'A world fact!'},
 rounds:[R.q('Which country has the Amazon rainforest?',['Brazil','Iceland','Canada'],'Brazil'),R.q('Is Iceland’s climate warm or cold?',['cold','warm'],'cold'),
  R.q('A big spray of hot water from underground is a…',['geyser','glacier','volcano'],'geyser'),R.q('A big block of ice that moves slowly is a…',['glacier','geyser','hot spring'],'glacier',{set:{row:['ice'],keep:true}}),
  R.q('A mountain with an opening where lava comes out is a…',['volcano','glacier','river'],'volcano',{set:{row:['volcano'],keep:true}}),R.q('Brazil lies on the…',['Equator','North Pole','Arctic Ocean'],'Equator'),
  R.sort('Brazil or Iceland?',['Brazil','Iceland'],[['parrot',0,'toucans'],['volcano',1,'volcanoes'],['monkey',0,'monkeys'],['ice',1,'glaciers']]),R.q('Iceland is in which hemisphere?',['Northern','Southern'],'Northern'),
  R.q('Why are there so many animals in Brazil?',['warm and wet, with lots of food','it is icy','there are no trees'],'warm and wet, with lots of food'),R.q('Where did Uncle Finn swim?',['in a hot spring','in the Amazon','in a glacier'],'in a hot spring'),
  R.q('In "Did you know?", about how many kinds of birds live in Brazil?',['1,700','17','7'],'1,700'),R.tf('Brazil is mostly in the Southern Hemisphere.',true)],
 tries:[['Would you rather visit Brazil or Iceland? Why?','*Brazil*, to see monkeys! or *Iceland*, to see a geyser!'],['What is a landform?','a natural shape of land: *mountain*, *volcano*…']]});

/* 15 ─ Our unique country: Nunavut and Vancouver */
U({id:'o15',title:'Life in Iqaluit and Vancouver',strand:'Global Communities',codes:['B1','B2','B3'],
 guide:{goal:'Compare life in Iqaluit, Nunavut, and Vancouver, British Columbia: how climate and location shape transportation, food, sports and daily life.',words:'Iqaluit, Nunavut, sealift, Vancouver, transit, ferry, similarity, difference',ask:['How do people travel between towns in Nunavut?','What is a sealift?','What is one way life is the same in both places?'],home:'Find Iqaluit and Vancouver on a map of Canada. How far apart are they?'},
 watch:['Same country, different lives!','In Iqaluit, there are no roads between towns, so people fly in small planes.'],
 fig:'Life in the Arctic and life on the west coast.',
 page:{story:{title:'Pen Pals across Canada',text:'Aputi lives in *Iqaluit, Nunavut*, in the Arctic. Sam lives in *Vancouver, British Columbia*, by the Pacific Ocean. Aputi wrote, "There are no roads between our towns, so we fly in *small planes*. In summer, a *sealift* ship brings canned food and supplies. I love *dog sledding* and *hockey*!" Sam wrote, "I take the *bus* and the *ferry*. There are lots of *stores*. In summer I go *hiking*, and in winter I go *skiing* on the mountains!"',pics:['airplane','ship','sled','bus']},
  boxes:[{title:'Iqaluit, Nunavut',ex:[['airplane','*planes*'],['ship','*sealift*'],['sled','*dog sleds*'],['hockey','*hockey*']]},
   {title:'Vancouver, B.C.',ex:[['bus','*buses*'],['store','*stores*'],['mountain','*hiking*'],['skier','*skiing*']]}],
  cards:[{q:'One similarity?',a:'both have *winter sports* and both are in *Canada*'},{q:'One difference?',a:'Iqaluit has *no roads* between towns; Vancouver has *buses* and *ferries*'}],
  words:[['sealift','ships that bring supplies to the Arctic in summer'],['similarity','a way two things are alike']]},
 steps:[
  {say:'Read the story',speech:'Aputi lives in Iqaluit, Nunavut. There are no roads between towns, so people fly in small planes. A sealift ship brings food in summer. Sam lives in Vancouver. He takes the bus and the ferry, and goes hiking and skiing.',set:S.row(['airplane','ship','bus','skier'],{labels:['planes','sealift','bus','skiing']}),
   cues:[['small planes','airplane','Iqaluit'],['A sealift ship','ship','Iqaluit'],['the bus and the ferry','bus','Vancouver'],['skiing','skier','Vancouver']]},
  {say:'Life in Iqaluit',speech:'In Iqaluit, drinking water and heating oil are shipped in, and every home gets a careful amount. Winter sports like hockey, curling and dog sledding are popular.',set:S.row(['water','fuel','hockey','sled'],{labels:['water','heating oil','hockey','dog sled']}),
   cues:[['drinking water','water','shipped'],['heating oil','fuel','shipped'],['hockey','hockey','sports'],['dog sledding','sled','sports']]},
  {say:'Life in Vancouver',speech:'In Vancouver, there are many stores and restaurants, so it is easy to get what you need. BC Transit buses and BC Ferries help people travel.',set:S.row(['store','bus','ship'],{labels:['stores','buses','ferries']}),
   cues:[['many stores','store','stores'],['buses','bus','transit'],['Ferries','ship','ferry']]},
  {say:'Alike and different',speech:'Both places are in Canada, and people in both enjoy winter sports. But Iqaluit has no roads between towns, while Vancouver has lots of transportation.',set:S.sort(['Iqaluit','both','Vancouver'],[['sled',0,'dog sled'],['canada',1,'Canada'],['bus',2,'city bus']]),
   cues:[['Both','bin:both','same'],['Iqaluit','bin:Iqaluit','different'],['Vancouver','bin:Vancouver','different','play']]}],
 more:{title:'Did you know?',text:'In *Iqaluit*, in June, the sun barely sets: it stays light almost all night! In December, there are only about *four hours* of daylight. People celebrate the return of the sun every year.',pics:['sun','moon','snowflake','night'],lead:'A Canada fact!'},
 rounds:[R.q('How do people travel between towns in Nunavut?',['by small plane','by subway','by bus'],'by small plane',{set:{row:['airplane'],keep:true}}),R.q('What brings supplies to the Arctic in summer?',['a sealift ship','a train','a truck'],'a sealift ship'),
  R.q('Which sports are popular in Iqaluit?',['hockey and dog sledding','surfing','baseball only'],'hockey and dog sledding'),R.q('How does Sam get around Vancouver?',['bus and ferry','dog sled','small plane'],'bus and ferry'),
  R.q('What does Sam do in winter?',['skiing','surfing','swimming in the sea'],'skiing'),R.q('Which city is by the Pacific Ocean?',['Vancouver','Iqaluit'],'Vancouver'),
  R.sort('Iqaluit or Vancouver?',['Iqaluit','Vancouver'],[['sled',0,'dog sled'],['bus',1,'city bus'],['airplane',0,'small plane'],['store',1,'many stores']]),R.q('What is one *similarity*?',['both are in Canada','both have no roads','both are hot'],'both are in Canada'),
  R.q('What is one *difference*?',['Iqaluit has no roads between towns','both have winter','both are in Canada'],'Iqaluit has no roads between towns'),R.tf('In Iqaluit, water and heating oil are shipped to the people.',true),
  R.q('In "Did you know?", how much daylight does Iqaluit get in December?',['about four hours','all day','none at all'],'about four hours'),R.q('Which province is Vancouver in?',['British Columbia','Nunavut','Ontario'],'British Columbia')],
 tries:[['How do you travel in your town?','*car*, *bus*, *bike*, *walking*…'],['Name one thing the same about your town and Iqaluit.','we both have *winter*, *schools*, *hockey*…']]});

/* 16 ─ Travel around the world */
U({id:'o16',title:'Travel around the world',strand:'Global Communities',codes:['B1','B2','B3'],
 guide:{goal:'Describe features of countries (China, Japan, Mali, Thailand) and natural environments (savannah, rainforest, desert) and the animals that live there.',words:'savannah, rainforest, desert, country, environment, native',ask:['What animal is native to China?','What is a savannah?','Which animals live in the desert?'],home:'Pick a country you would like to visit. Find three interesting facts about it.'},
 watch:['Pack your bags!','A savannah is a big grassland where elephants and zebras graze.'],
 fig:'Three natural environments and their animals.',
 page:{story:{title:'The Travel Club Photos',text:'The Travel Club shared photos from their trips. Lily went to *China* and saw a *panda* munching bamboo. Ken went to *Japan*, an island country full of *seafood* and sushi. Awa visited family in *Mali* and stood under a giant *baobab tree*. Tom went to *Thailand* and saw golden *Buddhist temples*. Then they looked at photos of a *savannah*, a *rainforest* and a *desert*, and guessed which animals live in each.',pics:['panda','fish','tree','temple']},
  boxes:[{title:'Countries',ex:[['panda','China: *pandas* eat bamboo'],['fish','Japan: *seafood*, sushi'],['tree','Mali: *baobab* tree'],['temple','Thailand: *temples*']],cols:2},
   {title:'Natural environments',ex:[['lion','savannah: *grassland*'],['monkey','rainforest: *lots of rain*'],['camel','desert: *little rain*']],cols:3}],
  cards:[{q:'Which environment gets lots of rain?',a:'the *rainforest*'},{q:'Which animal lives in the desert?',pics:['camel'],a:'the *camel* (and scorpions)'}],
  words:[['savannah','a large, flat grassland with some trees'],['environment','the land, water, weather and living things around us']]},
 steps:[
  {say:'Read the story',speech:'Lily saw a panda munching bamboo in China. Ken ate seafood in Japan, an island country. Awa stood under a giant baobab tree in Mali. Tom saw golden temples in Thailand.',set:S.row(['panda','fish','tree','temple'],{labels:['China','Japan','Mali','Thailand']}),
   cues:[['a panda','panda','China'],['seafood','fish','Japan'],['baobab tree','tree','Mali'],['golden temples','temple','Thailand']]},
  {say:'The savannah',speech:'A savannah in Africa is a large grassland with some trees. Elephants, zebras and cheetahs live there, and animals graze on the grass.',set:S.row(['elephant','zebra','lion'],{labels:['elephant','zebra','cheetah']}),
   cues:[['Elephants','elephant','savannah'],['zebras','zebra','graze']]},
  {say:'The rainforest',speech:'A rainforest in South America gets lots of rain. It is a very big forest with lots of wildlife, like toucans, gorillas and monkeys.',set:S.row(['parrot','monkey','frog'],{labels:['toucan','monkey','frog']}),
   cues:[['lots of rain','parrot','rainforest'],['wildlife','monkey','animals']]},
  {say:'The desert',speech:'A desert in the United States gets very little rain. It has lots of sand and few plants and animals: camels, scorpions and lizards.',set:S.sort(['savannah','rainforest','desert'],[['zebra',0],['parrot',1],['camel',2],['elephant',0],['scorpion',2]]),
   cues:[['savannah','bin:savannah','grass'],['rainforest','bin:rainforest','rain'],['desert','bin:desert','sand','play']]}],
 more:{title:'Did you know?',text:'A *baobab tree* can live for more than a thousand years! Its thick trunk stores water for dry times. Its fruit has lots of vitamin C, and people make drinks and snacks from it.',pics:['tree','water','juice','sun'],lead:'A world fact!'},
 rounds:[R.q('Which country has wild pandas?',['China','Mali','Canada'],'China',{set:{row:['panda'],keep:true}}),R.q('What do pandas eat?',['bamboo','fish','grass seeds'],'bamboo'),
  R.q('Which island country is famous for sushi and seafood?',['Japan','Mali','Thailand'],'Japan'),R.q('In which country did Awa see a baobab tree?',['Mali','Japan','China'],'Mali'),
  R.q('Thailand has many…',['Buddhist temples','glaciers','penguins'],'Buddhist temples'),R.sort('Which environment?',['savannah','rainforest','desert'],[['zebra',0],['parrot',1],['camel',2],['elephant',0],['monkey',1],['scorpion',2]]),
  R.q('A savannah is a large…',['grassland','ocean','glacier'],'grassland'),R.q('A rainforest gets lots of…',['rain','snow','sand'],'rain'),
  R.q('A desert has lots of…',['sand','snow','rain'],'sand'),R.q('Which animal grazes on the savannah?',['zebra','toucan','penguin'],'zebra'),
  R.q('In "Did you know?", how long can a baobab tree live?',['more than a thousand years','one year','ten days'],'more than a thousand years'),R.tf('A desert gets very little rain.',true)],
 tries:[['Name an animal of the rainforest.','a *toucan*, a *monkey*, a *sloth*'],['Which country would you visit? Why?','*Japan*, to eat sushi!']]});

/* 17 ─ Basic needs */
U({id:'o17',title:'Our basic needs',strand:'Global Communities',codes:['B1','B3'],
 guide:{goal:'Name basic needs (water, food, shelter, transportation) and compare how people meet them in different places, like the Arctic, Paris and Taipei.',words:'basic needs, water, food, shelter, transportation, Inuit',ask:['What are basic needs?','How do Inuit families get food?','Why might people use a mule in the mountains?'],home:'Make a chart: how does your family get water, food, shelter and transportation?'},
 watch:['Everyone needs the same things!','Water, food, shelter and a way to get around: we meet these needs in different ways.'],
 fig:'Ways people meet their needs around the world.',
 page:{story:{title:'How Do You Get Around?',text:'Kids around the world shared how they meet their needs. Nuka, an *Inuit* girl in the Arctic, said, "My family gets food by *hunting* and *fishing*, and also from the store. We travel by *snowmobile* and small boat." Marc in *Paris, France*, said, "I take the *subway* to school; it is the fastest way." Mei in *Taipei, Taiwan*, said, "My mom rides a *scooter* to work." And Carlos in the rocky hills of *Colorado* said, "I ride a *mule* along the narrow paths!"',pics:['girl','train','scooter','horse']},
  boxes:[{title:'Basic needs',ex:[['water','water'],['bread','food'],['house','shelter'],['bus','transportation']],cols:4},
   {title:'Different ways',lines:['water: from *taps*, *trucks*, *bottles*','food: from *stores*, *hunting*, *fishing*','shelter: *apartment*, *house*, *igloo* (long ago)','transportation: *subway*, *scooter*, *mule*, *snowmobile*']}],
  cards:[{q:'Why does Marc take the subway?',a:'it is the *fastest* way in a big city'},{q:'Why does Carlos ride a mule?',a:'the paths are *rocky* and *narrow*'}],
  words:[['basic needs','things everyone needs to live'],['shelter','a place that protects you from weather']]},
 steps:[
  {say:'Read the story',speech:'Nuka, an Inuit girl in the Arctic, gets food by hunting, fishing and from the store. Marc in Paris takes the subway. Mei’s mom in Taipei rides a scooter. Carlos in Colorado rides a mule along narrow paths.',set:S.row(['girl','train','scooter','horse'],{labels:['Arctic','Paris','Taipei','Colorado']}),
   cues:[['Nuka','girl','hunting, fishing'],['the subway','train','Paris'],['a scooter','scooter','Taipei'],['a mule','horse','Colorado']]},
  {say:'Four basic needs',speech:'Everyone needs water, food, shelter and a way to get around: transportation.',set:S.row(['water','bread','house','bus']),
   cues:[['water','water','water'],['food','bread','food'],['shelter','house','shelter'],['transportation','bus','transport']]},
  {say:'Different ways',speech:'People meet their needs in different ways depending on where they live. Water can come from a tap, a water truck or a bottle.',set:S.row(['shower','truck','bottle'],{labels:['tap','water truck','bottle']}),
   cues:[['a tap','shower','tap'],['a water truck','truck','truck'],['a bottle','bottle','bottle']]},
  {say:'You and the Inuit',speech:'Compare: Nuka’s family hunts and fishes and also shops. Your family might shop at a grocery store. Both families meet the same needs!',set:S.sort(['Nuka','both','me'],[['fish',0,'fishing'],['house',1,'a home'],['shopping cart',2,'grocery store']]),
   cues:[['Nuka','bin:Nuka','Arctic'],['Both','bin:both','same needs','play']]}],
 more:{title:'Did you know?',text:'In some Arctic communities, families still make *qamutiks*, long wooden sleds pulled by snowmobiles or dogs. A qamutik can carry people, tents, food and gear across the snow and ice for many kilometres.',pics:['sled','dog','snowflake','tent'],lead:'An Arctic fact!'},
 rounds:[R.q('Which one is a *basic need*?',['food','a video game','a trophy'],'food'),R.q('What is *shelter*?',['a place that protects you','a kind of food','a bus'],'a place that protects you'),
  R.q('How does Marc get to school in Paris?',['subway','mule','scooter'],'subway',{set:{row:['train'],keep:true}}),R.q('Why does Marc take the subway?',['it is the fastest way','it is the slowest','it is a boat'],'it is the fastest way'),
  R.q('Who rides a scooter to work in Taipei?',['Mei’s mom','Carlos','Nuka'],'Mei’s mom'),R.q('Why does Carlos ride a mule?',['the paths are rocky and narrow','mules can fly','it is a city'],'the paths are rocky and narrow'),
  R.q('How does Nuka’s family get food?',['hunting, fishing and the store','only from a farm','from a vending machine'],'hunting, fishing and the store'),R.sort('Which basic need?',['food','transportation'],[['bread',0],['bus',1],['fish',0],['scooter',1]]),
  R.q('Where can water come from?',['taps, trucks or bottles','clouds only','the oven'],'taps, trucks or bottles'),R.tf('Everyone has the same basic needs.',true),
  R.q('In "Did you know?", what is a qamutik?',['a long wooden sled','a kind of fish','a house'],'a long wooden sled'),R.q('Which city is in France?',['Paris','Taipei','Iqaluit'],'Paris')],
 tries:[['How does your family get water?','from the *tap*'],['Name a kind of shelter.','*house*, *apartment*, *tent*']]});

/* 18 ─ Living around the world */
U({id:'o18',title:'Homes and food around the world',strand:'Global Communities',codes:['B1','B2','B3'],
 guide:{goal:'Describe homes (ger in Mongolia, stilt houses in Malaysia, timber houses in Germany) and how families around the world get their food.',words:'ger, yurt, stilt house, timber frame, herd, rural, village',ask:['Why do some families in Mongolia move their homes?','Why are some houses built on stilts?','Where does your food come from?'],home:'Draw a house that would fit where you live. What materials would you use?'},
 watch:['Homes that fit the place!','A ger can be packed up and moved when the animals need new grass.'],
 fig:'Different homes around the world.',
 page:{story:{title:'Bataar’s Moving Home',text:'*Bataar* lives in rural *Mongolia*. His family lives in a *ger*, a round tent made of white felt and wool on wooden poles. "Our animals give us *milk* and *meat*," he says. "When they eat all the grass, we pack up our ger and move to a new place." Far away in *Malaysia*, Annisa’s village has *stilt houses* over the water, built from mangrove wood. In *Germany*, Klaus lives in a house with painted *bricks* and wooden frames.',pics:['tent','milk','house','fish']},
  boxes:[{title:'Homes',ex:[['tent','*ger*: Mongolia, moves with the herd'],['house','*stilt house*: Malaysia, over water'],['brick','*timber-frame house*: Germany']],cols:3},
   {title:'Getting food',lines:['Mongolia: *milk* and *meat* from animals','Canada’s Arctic: *hunting* seals and fishing','France: pastries from the *bakery*','Indonesia: growing *rice*, catching *fish*']}],
  cards:[{q:'Why are some homes on stilts?',a:'to stay *above the water*'},{q:'Why do Bataar’s family move?',a:'to find *fresh grass* for their animals'}],
  words:[['ger','a round, movable home of felt (also called a yurt)'],['rural','in the countryside, not a city']]},
 steps:[
  {say:'Read the story',speech:'Bataar lives in a ger in Mongolia, a round tent of felt on wooden poles. When the animals eat all the grass, they move. In Malaysia, Annisa lives in a stilt house over the water. In Germany, Klaus lives in a house with bricks and wooden frames.',set:S.row(['tent','house','brick'],{labels:['ger','stilt house','timber house']}),
   cues:[['a ger','tent','Mongolia'],['a stilt house','house','Malaysia'],['bricks and wooden frames','brick','Germany']]},
  {say:'Homes fit the place',speech:'Homes are built to fit where people live. A ger is easy to move. A stilt house stays above the water. A strong brick house keeps out the cold.',set:S.row(['tent','water','brick'],{labels:['easy to move','above water','keeps out cold']}),
   cues:[['easy to move','tent','move'],['above the water','water','stilts'],['keeps out the cold','brick','strong']]},
  {say:'Getting food',speech:'Bataar’s family gets milk and meat from their animals. Akycha in the Arctic hunts seals with his father. Jacques in France buys pastries from the bakery. Annisa’s family grows rice and catches fish.',set:S.row(['milk','seal','bread','rice'],{labels:['milk and meat','seals','bakery','rice and fish']}),
   cues:[['milk and meat','milk','Mongolia'],['hunts seals','seal','Arctic'],['the bakery','bread','France'],['grows rice','rice','Indonesia']]},
  {say:'Match the riddle',speech:'I am moved to a new place when the grass is gone. White cloth, wool and poles make me strong. What am I? A ger!',set:S.row(['tent'],{labels:['a ger!']}),
   cues:[['A ger','tent','ger']]}],
 more:{title:'Did you know?',text:'A *ger* can be taken down in about an hour and loaded onto camels or a truck! Inside, there is a stove in the middle for cooking and heat, and the door usually faces south, toward the sun.',pics:['tent','camel','fire','sun'],lead:'A world fact!'},
 rounds:[R.q('What is a *ger*?',['a round, movable felt home','a boat','a brick tower'],'a round, movable felt home',{set:{row:['tent'],keep:true}}),R.q('Why does Bataar’s family move?',['to find fresh grass for their animals','to go to school','because of a storm'],'to find fresh grass for their animals'),
  R.q('Where are stilt houses built in the story?',['over the water in Malaysia','in the desert','on glaciers'],'over the water in Malaysia'),R.q('Klaus’s house in Germany has…',['bricks and wooden frames','felt walls','ice blocks'],'bricks and wooden frames'),
  R.q('What do Bataar’s animals give the family?',['milk and meat','eggs and honey','wool hats'],'milk and meat'),R.q('Where does Jacques buy pastries?',['the bakery','the river','the farm'],'the bakery'),
  R.q('How does Annisa’s family get food?',['grow rice and catch fish','hunt seals','buy pastries'],'grow rice and catch fish'),R.sort('Which home?',['ger','stilt house'],[['tent',0,'felt walls'],['water',1,'over water'],['horse',0,'moves with herd'],['fish',1,'fish below']]),
  R.q('*Rural* means…',['in the countryside','in a big city','under the sea'],'in the countryside'),R.tf('Homes are built to fit the place where people live.',true),
  R.q('In "Did you know?", how long does it take to take down a ger?',['about an hour','a year','one minute'],'about an hour'),R.q('Which way does a ger’s door usually face?',['south','north','down'],'south')],
 tries:[['What is your home made of?','*wood*, *brick*, *concrete*…'],['Name one way people get food.','*farming*, *fishing*, *shopping*']]});

/* 19 ─ Clothes and homes for the climate */
U({id:'o19',title:'Clothes and homes for the climate',strand:'Global Communities',codes:['B1','B2'],
 guide:{goal:'Explain how traditional clothes and building materials (snow blocks, mud bricks, cob) protect people from the climate.',words:'sari, poncho, parka, igloo, adobe, mud brick, cob, climate',ask:['Why is a sari good for hot weather?','What was an igloo made of?','How does an adobe house stay cool?'],home:'Look in your closet: which clothes are for hot weather and which for cold?'},
 watch:['Dress for the weather!','A parka keeps you warm in freezing Nunavut. A light sari keeps you cool in hot Delhi.'],
 fig:'Clothes and homes that fit hot, cold and wet places.',
 page:{story:{title:'The Costume Parade',text:'For Heritage Day, kids wore clothes from around the world. Riya wore a bright *sari* from *Delhi, India*: "The light fabric keeps me cool in the heat." Mateo wore a *poncho* from *Lima, Peru*: "It can be cold in the mountains." Nia wore a long robe from *Nairobi, Kenya*: "It protects me from the sun." Ivan wore a warm *parka* from *Nunavut*: "It keeps me warm in freezing temperatures all year!"',pics:['dress','coat','sun','snowflake']},
  boxes:[{title:'Clothes for the climate',ex:[['dress','*sari*: cool in hot Delhi'],['scarf','*poncho*: warm in the mountains of Peru'],['shirt','*robe*: sun protection in Kenya'],['coat','*parka*: warm in Nunavut']],cols:2},
   {title:'Building materials',ex:[['igloo','*snow blocks*: igloo, traps heat'],['brick','*mud bricks*: adobe, cool by day, warm at night'],['house','*cob*: sand, clay and water, soaks up rain']],cols:3}],
  cards:[{q:'Which house fits very hot, dry Arizona?',a:'an *adobe* house'},{q:'Which house fits mild, very wet Britain?',a:'a *cob* house'}],
  words:[['adobe','a house of mud bricks that stays cool'],['parka','a long, warm, hooded coat']]},
 steps:[
  {say:'Read the story',speech:'Riya wore a sari from India: the light fabric keeps her cool. Mateo wore a poncho from Peru, for the cold mountains. Nia wore a robe from Kenya to protect her from the sun. Ivan wore a warm parka from Nunavut.',set:S.row(['dress','scarf','shirt','coat'],{labels:['sari','poncho','robe','parka']}),
   cues:[['a sari','dress','India'],['a poncho','scarf','Peru'],['a robe','shirt','Kenya'],['a warm parka','coat','Nunavut']]},
  {say:'Igloo',speech:'Long ago, Inuit hunters built igloos from blocks of snow. The dome shape traps heat inside.',set:S.row(['igloo','snowflake'],{labels:['igloo','snow blocks']}),
   cues:[['igloos','igloo','dome'],['blocks of snow','snowflake','snow']]},
  {say:'Adobe and cob',speech:'An adobe house is made of mud, straw, sand and water. It soaks up heat slowly, so it is cool in the day and warm at night. A cob house of sand, clay and water can soak up rain without getting soft.',set:S.row(['brick','house'],{labels:['adobe','cob']}),
   cues:[['An adobe house','brick','mud brick'],['A cob house','house','cob']]},
  {say:'Match the city',speech:'Nunavut is very cold and snowy: igloo. Arizona is very hot and dry: adobe. Devon in Britain is mild and very wet: cob.',set:S.sort(['cold','hot','wet'],[['igloo',0],['brick',1,'adobe'],['house',2,'cob']]),
   cues:[['very cold','bin:cold','igloo'],['very hot','bin:hot','adobe'],['very wet','bin:wet','cob','play']]}],
 more:{title:'Did you know?',text:'Some *adobe* buildings in the southwestern United States and Mexico are more than *1,000 years old*! Thick mud walls keep homes cool in the hot sun, and some families still build with adobe today.',pics:['brick','sun','house','cactus'],lead:'A world fact!'},
 rounds:[R.q('Which clothing keeps Riya cool in Delhi?',['a sari','a parka','mittens'],'a sari',{set:{row:['dress'],keep:true}}),R.q('Ivan wears a parka because Nunavut is…',['freezing','hot','dry'],'freezing'),
  R.q('A poncho is from…',['Peru','Kenya','India'],'Peru'),R.q('What was an igloo made of?',['snow blocks','mud bricks','cob'],'snow blocks',{set:{row:['igloo'],keep:true}}),
  R.q('An adobe house is made of…',['mud bricks','snow','glass'],'mud bricks'),R.q('Which house fits very hot, dry Arizona?',['adobe','igloo','cob'],'adobe'),
  R.q('Which house fits mild, very wet Devon, Britain?',['cob','igloo','adobe'],'cob'),R.sort('Hot or cold clothes?',['hot','cold'],[['dress',0,'sari'],['coat',1,'parka'],['shirt',0,'light robe'],['mitten',1,'mittens']]),
  R.q('Why does an igloo’s dome shape help?',['it traps heat inside','it lets snow in','it is fast'],'it traps heat inside'),R.tf('Nia’s robe protects her from the sun.',true),
  R.q('In "Did you know?", how old are some adobe buildings?',['more than 1,000 years','2 years','100 days'],'more than 1,000 years'),R.q('What does a cob house do in the rain?',['soaks it up without getting soft','melts','floats'],'soaks it up without getting soft')],
 tries:[['What do you wear on a hot day?','*shorts*, a *sun hat*…'],['What would you build a house with?','*wood*, *bricks*, *stone*…']]});

/* 20 ─ Sports and recreation */
U({id:'o20',title:'Sports and recreation',strand:'Global Communities',codes:['B1','B2'],
 guide:{goal:'Explain how climate and landforms shape the sports and outdoor activities people enjoy, in the world and across Canada.',words:'recreation, activity, climate, landform, mountain, lake',ask:['Why is skiing popular in Canada?','Where is surfing popular?','What activities can you do at a lake?'],home:'Plan a family outdoor day that fits this season.'},
 watch:['Play where you live!','Snowy mountains are great for skiing. Sunny beaches are great for surfing.'],
 fig:'Sports matched to the places that suit them.',
 page:{story:{title:'Summer Camp Choices',text:'At camp, the counsellors showed photos of Canada. "In *British Columbia*, the *mountains* are perfect for *hiking* and rock *climbing*. In *Quebec*, you can go *tubing* down snowy hills in winter. In *Alberta*, the open land is great for *biking*. And at *Lake Ontario*, you can *fish*, *kayak* or go *camping*." Around the world, people in snowy *Canada* love skiing, people in sunny *Hawaii* love surfing, and people in grassy *Britain* love soccer.',pics:['mountain','skier','cyclist','canoe']},
  boxes:[{title:'Sports and places',ex:[['skier','*skiing*: snowy Canada'],['swimmer','*surfing*: sunny Hawaii'],['ball','*soccer*: grassy Britain']],cols:3},
   {title:'Fun across Canada',lines:['British Columbia: *hiking*, *climbing*','Quebec: *tubing*, *skating*','Alberta: *biking*, *camping*','Lake Ontario: *fishing*, *kayaking*']}],
  cards:[{q:'Why do Canadians love winter sports?',a:'long, *snowy* winters and many *mountains*'},{q:'What can you do at a lake?',a:'*fish*, *kayak*, *swim*, *camp*'}],
  words:[['recreation','things people do for fun'],['landform','a natural shape of the land']]},
 steps:[
  {say:'Read the story',speech:'In British Columbia, mountains are perfect for hiking and climbing. In Quebec, you can go tubing. In Alberta, the open land is great for biking. At Lake Ontario, you can fish and kayak.',set:S.row(['mountain','sled','cyclist','canoe'],{labels:['B.C.: hike','Quebec: tubing','Alberta: bike','Lake Ontario: kayak']}),
   cues:[['British Columbia','mountain','hiking'],['Quebec','sled','tubing'],['Alberta','cyclist','biking'],['Lake Ontario','canoe','kayaking']]},
  {say:'Around the world',speech:'Canada has long, cold winters and snowy mountains: great for skiing. Hawaii is hot and sunny with beaches: great for surfing. Britain has lush grassland: great for soccer.',set:S.row(['skier','swimmer','ball'],{labels:['Canada','Hawaii','Britain']}),
   cues:[['skiing','skier','Canada'],['surfing','swimmer','Hawaii'],['soccer','ball','Britain']]},
  {say:'Water fun',speech:'Lakes and rivers are great for fishing, kayaking and swimming.',set:S.row(['fish','canoe','swimmer'],{labels:['fishing','kayaking','swimming']}),
   cues:[['fishing','fish','fish'],['kayaking','canoe','kayak']]},
  {say:'Match them',speech:'Match each sport with the place that fits it best.',set:S.sort(['snowy mountains','beach','grassland'],[['skier',0],['swimmer',1],['ball',2]]),
   cues:[['snowy mountains','bin:snowy mountains','skiing'],['beach','bin:beach','surfing'],['grassland','bin:grassland','soccer','play']]}],
 more:{title:'Did you know?',text:'*Ice hockey* and *lacrosse* are Canada’s two *national sports*! Lacrosse was first played by Indigenous peoples long ago, and hockey grew on Canada’s frozen ponds and lakes.',pics:['hockey','ice','canada','ball'],lead:'A Canada fact!'},
 rounds:[R.q('Which sport fits snowy mountains best?',['skiing','surfing','soccer'],'skiing',{set:{row:['skier'],keep:true}}),R.q('Which sport fits sunny Hawaii best?',['surfing','skiing','dog sledding'],'surfing'),
  R.q('Which sport fits grassy Britain best?',['soccer','skiing','surfing'],'soccer'),R.q('In British Columbia, the mountains are great for…',['hiking and climbing','surfing','sledding on sand'],'hiking and climbing'),
  R.q('What can you do at Lake Ontario?',['fish and kayak','ski down a glacier','ride camels'],'fish and kayak'),R.sort('Which place fits?',['snowy mountains','beach'],[['skier',0],['swimmer',1],['sled',0],['shell',1]]),
  R.q('What is *recreation*?',['things people do for fun','a kind of rock','school work'],'things people do for fun'),R.q('Why do many Canadians enjoy winter sports?',['long, snowy winters','it is always hot','no snow'],'long, snowy winters'),
  R.q('Where could you go tubing on snowy hills?',['Quebec','Hawaii','the Sahara'],'Quebec'),R.tf('Alberta’s open land is great for biking.',true),
  R.q('In "Did you know?", what are Canada’s national sports?',['hockey and lacrosse','soccer and golf','tennis and chess'],'hockey and lacrosse'),R.q('Who first played lacrosse?',['Indigenous peoples','astronauts','pirates'],'Indigenous peoples')],
 tries:[['What is your favourite outdoor activity?','*skating*, *biking*, *swimming*…'],['What sport fits your town in winter?','*skating*, *hockey*, *sledding*']]});

/* 21 ─ Foods from around the world */
U({id:'o21',title:'Foods from around the world',strand:'Global Communities',codes:['B1','B2','B3'],
 guide:{goal:'Find where foods in our grocery stores come from, and explain why some places can grow crops all year.',words:'import, grower, producer, crop, climate, soil, Equator',ask:['Where do bananas come from?','Why can some places grow food all year?','Where does your favourite fruit come from?'],home:'Read the labels on fruit at the grocery store. Find three countries.'},
 watch:['Food travels!','These bananas grew in Ecuador, near the Equator, and travelled all the way to Canada.'],
 fig:'Foods and the places they come from.',
 page:{story:{title:'The Grocery Detectives',text:'Mia and her dad became *grocery detectives*. They read the stickers on the fruit. The *bananas* came from *Ecuador*. The *grapes* came from *Chile*. The *kiwis* came from *New Zealand*, and the *oranges* came from *Florida*. "Why so far away?" asked Mia. "Some places have a *warm climate* and good *soil*, so crops grow *all year*," said Dad. "In winter, it is too cold to grow bananas in Canada!"',pics:['banana','grapes','kiwi','orange']},
  boxes:[{title:'Where food comes from',ex:[['banana','bananas: *Ecuador*'],['grapes','grapes: *Chile*'],['kiwi','kiwis: *New Zealand*'],['orange','oranges: *Florida*'],['tomato','tomatoes: *Mexico*'],['potato','potatoes: *Canada*']],cols:3},
   {title:'Why there?',lines:['many growers are *near the Equator*','*warm* all year','deep, well-drained *soil*','plenty of *sun* and *rain*']}],
  cards:[{q:'Why can bananas grow well in Ecuador?',a:'it is *hot*, near the *Equator*, with good *soil*'},{q:'Name a food grown in Canada.',a:'*potatoes*, *apples*, *wheat*, *maple syrup*'}],
  words:[['import','to bring in goods from another country'],['crop','a plant grown for food']]},
 steps:[
  {say:'Read the story',speech:'The bananas came from Ecuador. The grapes came from Chile. The kiwis came from New Zealand, and the oranges came from Florida. Some places have a warm climate and good soil, so crops grow all year.',set:S.row(['banana','grapes','kiwi','orange'],{labels:['Ecuador','Chile','New Zealand','Florida']}),
   cues:[['bananas','banana','Ecuador'],['grapes','grapes','Chile'],['kiwis','kiwi','New Zealand'],['oranges','orange','Florida']]},
  {say:'Near the Equator',speech:'Many food growers are near the Equator. It is warm all year, so crops like bananas, coffee and cocoa grow well.',set:S.row(['sun','banana','chocolate'],{labels:['warm all year','bananas','cocoa']}),
   cues:[['warm all year','sun','Equator'],['bananas','banana','bananas'],['cocoa','chocolate','cocoa']]},
  {say:'Grown in Canada',speech:'Canada grows food too: potatoes, apples, wheat, corn and maple syrup. But our winters are too cold for bananas!',set:S.row(['potato','apple','corn','maple leaf'],{labels:['potatoes','apples','corn','maple syrup']}),
   cues:[['potatoes','potato','Canada'],['apples','apple','Canada'],['maple syrup','maple leaf','Canada']]},
  {say:'Read the labels',speech:'Be a grocery detective! Read the sticker or label to find where a food comes from.',set:S.row(['shopping cart','banana'],{labels:['grocery store','label: Ecuador']}),
   cues:[['Read the sticker','banana','label']]}],
 more:{title:'Did you know?',text:'*Chocolate* comes from *cocoa beans* that grow in pods on trees near the Equator, in places like Ghana and Ecuador. It takes about 400 beans to make just half a kilogram of chocolate!',pics:['chocolate','tree','sun','globe'],lead:'A food fact!'},
 rounds:[R.q('Where did the bananas come from?',['Ecuador','Canada','Iceland'],'Ecuador',{set:{row:['banana'],keep:true}}),R.q('Where did the kiwis come from?',['New Zealand','Mexico','Japan'],'New Zealand'),
  R.q('Where did the grapes come from?',['Chile','Florida','Peru'],'Chile'),R.q('Where did the oranges come from?',['Florida','New Zealand','Chile'],'Florida'),
  R.q('Why can some places grow crops all year?',['warm climate and good soil','they have snow','they have no sun'],'warm climate and good soil'),R.q('Many food growers are near the…',['Equator','North Pole','South Pole'],'Equator'),
  R.q('Which food is grown in Canada?',['potatoes','bananas','cocoa'],'potatoes'),R.q('Juan lives in Ecuador. The climate there is very…',['hot','cold'],'hot'),
  R.q('What do plants need to stay healthy?',['deep, well-drained soil','plastic','ice'],'deep, well-drained soil'),R.tf('Canada’s winters are too cold to grow bananas outside.',true),
  R.q('In "Did you know?", about how many cocoa beans make half a kilogram of chocolate?',['about 400','about 4','about 4,000,000'],'about 400'),R.q('How can you find where a fruit came from?',['read its sticker or label','taste it','throw it'],'read its sticker or label')],
 tries:[['Where does your favourite fruit come from?','check the *sticker*!'],['Name a food grown in Ontario.','*apples*, *corn*, *tomatoes*…']]});

/* 22 ─ Where people live */
U({id:'o22',title:'Where people live',strand:'Global Communities',codes:['B2','B3'],
 guide:{goal:'Read a bar graph of Canada’s largest cities, find them on a map, and explain why most Canadians live in the south.',words:'population, city, province, bar graph, south, border',ask:['Which city in Canada has the most people?','In which province are many of the biggest cities?','Why do most Canadians live in the south?'],home:'Find your town or city on a map of Canada. Is it in the north or the south?'},
 watch:['Where do most Canadians live?','Most big cities are in the south of Canada, where it is warmer.'],
 fig:'A bar graph of big cities, and a map of Canada.',
 page:{story:{title:'Counting Canadians',text:'Our class looked at a *bar graph* of the *biggest cities* in Canada. *Toronto* had the longest bar, then *Montreal*, then *Vancouver*. Many big cities, like Toronto, Ottawa, Mississauga, Brampton and Hamilton, are in *Ontario*. Then we found the cities on a *map*. "Most of them are in the *south*, close to the United States border!" said Omar. Our teacher said the south is *warmer*, with good land for farming and easy travel.',pics:['city','map','canada','train']},
  boxes:[{title:'Biggest cities',lines:['1. *Toronto*, Ontario','2. *Montreal*, Quebec','3. *Vancouver*, British Columbia','also: Calgary, Edmonton, Ottawa, Winnipeg…']},
   {title:'Why the south?',lines:['*warmer* climate','good *farmland*','*rivers* and *lakes*','easy *travel* and trade']}],
  cards:[{q:'In which province are many big cities?',a:'*Ontario*'},{q:'What is population?',a:'the *number of people* living in a place'}],
  words:[['population','the number of people living in a place'],['province','one of the big parts of Canada, like Ontario']]},
 steps:[
  {say:'Read the story',speech:'Toronto had the longest bar, then Montreal, then Vancouver. Many big cities are in Ontario. On the map, most of them are in the south, close to the United States border, where it is warmer.',set:{custom:'graph',cats:['city','city','city'],labels:['Toronto','Montreal','Vancouver'],v:[6,4,3]},
   cues:[['Toronto','city','biggest']]},
  {say:'On the map',speech:'Look at the map. The big cities are in the south part of Canada. The north has fewer people.',set:G({C2:'city',C3:'city',C4:'city',A3:'snowflake'}),
   cues:[['in the south','city','south'],['The north','snowflake','fewer people']]},
  {say:'Why the south?',speech:'Most Canadians live in the south because it is warmer, there is good farmland, and there are rivers, lakes and roads for travel.',set:S.row(['sun','corn','river','train'],{labels:['warmer','farmland','water','travel']}),
   cues:[['warmer','sun','warm'],['farmland','corn','farms'],['travel','train','travel']]},
  {say:'Population',speech:'Population is the number of people who live in a place. Big cities have big populations.',set:S.row(['people','city'],{labels:['people','city']}),
   cues:[['Population','people','how many']]}],
 more:{title:'Did you know?',text:'About *9 out of 10* Canadians live within a few hours’ drive of the United States border! Yet Canada is so big that some northern places have more caribou than people.',pics:['canada','car','moose','snowflake'],lead:'A Canada fact!'},
 rounds:[R.q('Which city has the *most* people?',['Toronto','Montreal','Hamilton'],'Toronto',{set:{custom:'graph',cats:['city','city','city'],labels:['Toronto','Montreal','Vancouver'],v:[6,4,3]}}),R.q('Which city is *second*?',['Montreal','Vancouver','Calgary'],'Montreal'),
  R.q('Which city is *third*?',['Vancouver','Winnipeg','Edmonton'],'Vancouver'),R.q('In which province are many of the biggest cities?',['Ontario','Nunavut','Yukon'],'Ontario'),
  R.q('Where do most Canadians live?',['in the south','in the far north','on islands'],'in the south'),R.q('Why do many people live in the south?',['warmer, with good farmland','it is icy','there are no roads'],'warmer, with good farmland'),
  R.q('What is *population*?',['the number of people in a place','a kind of map','the weather'],'the number of people in a place'),R.q('Which city is in Quebec?',['Montreal','Calgary','Vancouver'],'Montreal'),
  R.grid('On the map, tap a southern city.',{rows:3,cols:5,items:{C3:'city',A2:'snowflake'}},'C3'),R.tf('The north of Canada has fewer people than the south.',true),
  R.q('In "Did you know?", how many Canadians live near the U.S. border?',['about 9 out of 10','about 1 out of 10','none'],'about 9 out of 10'),R.q('A bar graph’s longest bar shows…',['the most','the least'],'the most')],
 tries:[['What is the biggest city near you?','*Toronto*, *Ottawa*, *London*…'],['Name a province.','*Ontario*, *Quebec*, *Alberta*…']]});

/* 23 ─ Adapting to a place */
U({id:'o23',title:'Adapting to a place',strand:'Global Communities',codes:['B1','B2'],
 guide:{goal:'Explain how people adapt to where they live: growing crops that fit, working at cooler times, and choosing clothes for the climate.',words:'adapt, adjust, climate, humid, outfit',ask:['Why do people in Managua work early in the morning?','How do people in the Arctic get food in winter?','What would you pack for Florida?'],home:'Look at a weather forecast for a faraway city. Pack an imaginary suitcase for it.'},
 watch:['Adapt to fit in!','In Florida, people grow coconut palms because they love hot, wet weather.'],
 fig:'People adapting to hot, wet and frozen places.',
 page:{story:{title:'How We Adapt',text:'Three kids explained how their families *adapt*. Lucas in *Florida* said, "It is humid and rainy, and the ground never freezes, so we grow *coconut palms*." Sofia in *Managua, Nicaragua*, said, "It is very hot during the day, so we finish work early in the *morning* when it is cooler." Ataata in the *Arctic* said, "The sea is frozen all year near us, so we *cut through the ice* to fish." Every family adapts to its place!',pics:['palm','sun','ice','fish']},
  boxes:[{title:'Ways to adapt',ex:[['palm','*grow* crops that fit'],['sunrise','*work* when it is cooler'],['fish','*fish* through the ice'],['coat','*dress* for the weather']],cols:2},
   {title:'Packing for the climate',lines:['Managua (hot): *tank top*, *shorts*, *sunscreen*','Florida (humid, rainy): *cotton shirt*, *umbrella*, *sandals*','the Arctic (frozen): *parka*, *toque*, *mittens*, *winter boots*'],cols:1}],
  cards:[{q:'What does adapt mean?',a:'to *change* to fit where you live'},{q:'What would you wear in the Arctic?',a:'a *goose down parka*, *mittens*, a *toque*'}],
  words:[['adapt','to change to fit a place'],['humid','damp and sticky air']]},
 steps:[
  {say:'Read the story',speech:'In Florida, it is humid and rainy, so Lucas’s family grows coconut palms. In Managua, it is very hot, so Sofia’s family works early in the morning. In the Arctic, the sea is frozen, so Ataata’s family cuts through the ice to fish.',set:S.row(['palm','sunrise','ice'],{labels:['Florida','Managua','the Arctic']}),
   cues:[['coconut palms','palm','Florida'],['early in the morning','sunrise','Managua'],['cuts through the ice','ice','Arctic']]},
  {say:'Adapt',speech:'To adapt means to change to fit the place you live. People adapt what they grow, when they work, and what they wear.',set:S.row(['palm','alarm clock','coat'],{labels:['what we grow','when we work','what we wear']}),
   cues:[['what they grow','palm','grow'],['when they work','alarm clock','work'],['what they wear','coat','wear']]},
  {say:'Pack for the place',speech:'In hot Managua, wear a tank top and sunscreen. In rainy Florida, bring an umbrella. In the frozen Arctic, wear a parka, a toque and mittens.',set:S.sort(['hot','rainy','frozen'],[['shirt',0,'tank top'],['umbrella',1],['coat',2,'parka'],['sunglasses',0],['mitten',2]]),
   cues:[['hot Managua','bin:hot','hot'],['rainy Florida','bin:rainy','rain'],['frozen Arctic','bin:frozen','cold','play']]},
  {say:'Every family',speech:'Every family adapts to its place. How does your family adapt to winter, or to a hot summer?',set:S.row(['family','snowflake','sun'],{labels:['my family','winter','summer']}),
   cues:[['adapts','family','adapt']]}],
 more:{title:'Did you know?',text:'In very hot countries, many buildings are painted *white*. White reflects the sunlight, so the house stays cooler inside. In cold places, darker colours can soak up a little extra warmth from the sun.',pics:['house','sun','paintbrush','snowflake'],lead:'A world fact!'},
 rounds:[R.q('What does *adapt* mean?',['change to fit a place','stay the same','run away'],'change to fit a place'),R.q('Why does Lucas’s family grow coconut palms?',['they grow well in hot, wet places','they like snow','they are blue'],'they grow well in hot, wet places',{set:{row:['palm'],keep:true}}),
  R.q('Why does Sofia’s family work early in the morning?',['it is cooler then','it is dark','they like breakfast'],'it is cooler then'),R.q('How does Ataata’s family get fish?',['cut through the ice','buy only pizza','fish from a plane'],'cut through the ice'),
  R.sort('Which climate is this outfit for?',['hot','frozen'],[['shirt',0,'tank top'],['coat',1,'parka'],['sunglasses',0],['mitten',1]]),R.q('What would you pack for rainy Florida?',['an umbrella','winter boots','a toque'],'an umbrella'),
  R.q('What would you wear in the frozen Arctic?',['a goose down parka','sandals','a tank top'],'a goose down parka'),R.q('*Humid* means…',['damp and sticky air','very dry','freezing'],'damp and sticky air'),
  R.q('What should you wear in hot Managua?',['sunscreen and light clothes','a woollen scarf','insulated pants'],'sunscreen and light clothes'),R.tf('Every family adapts to the place where it lives.',true),
  R.q('In "Did you know?", why are many houses in hot countries white?',['white reflects sunlight','white is cheap','they forgot to paint'],'white reflects sunlight'),R.q('A toque is a…',['warm winter hat','kind of boat','fruit'],'warm winter hat')],
 tries:[['How does your family adapt to winter?','*warm coats*, *shovelling snow*, *indoor play*…'],['What would you pack for a beach?','*swimsuit*, *sunscreen*, *hat*']]});

/* 24 ─ Preserving our resources */
U({id:'o24',title:'Taking care of our resources',strand:'Global Communities',codes:['B1','B3'],
 guide:{goal:'Explain why we must preserve resources like fresh water, soil and forests, and tell which actions help and which harm.',words:'resource, preserve, fresh water, forest, electricity, future generations',ask:['Why is fresh water important?','Which action destroys forests?','What can you do to save electricity?'],home:'Make a family "resource saver" list: turn off lights, take short showers, grow a plant.'},
 watch:['Save it for later!','Turning off the lights saves electricity. Growing a garden gives us fresh food.'],
 fig:'Actions that save resources, and one that destroys them.',
 page:{story:{title:'The Resource Savers',text:'Ms. Kahn showed a map of *fresh water* around the world. "Some places have *a lot* of fresh water, like Canada. Some have *very little*." Ben’s family *plants a garden* so they can grow their own food all summer. Kiki and her brother *turn off the lights* when they leave a room, to *save electricity*. But in the third picture, workers were *clearing a forest* to build a wider road. "Which one does *not* save our resources?" asked Ms. Kahn.',pics:['water','seedling','light bulb','tree']},
  boxes:[{title:'Resources',text:'*Resources* are things from nature that we use. We must *preserve* them for *future generations*.',ex:[['water','fresh water'],['seedling','soil'],['tree','forests'],['rock','minerals']]},
   {title:'Actions and results',lines:['garden → *grow food*','lights off → *save electricity*','cut down a forest → *harm*']}],
  cards:[{q:'Name a continent with a lot of fresh water.',a:'*North America*'},{q:'One way to preserve water?',a:'*turn off the tap*, fix leaks, short showers'}],
  words:[['resource','something from nature that people use'],['preserve','to keep safe so it lasts']]},
 steps:[
  {say:'Read the story',speech:'Some places have a lot of fresh water, and some have very little. Ben’s family plants a garden to grow their own food. Kiki turns off the lights to save electricity. But workers cleared a forest to build a wider road. Which one does not save our resources?',set:S.row(['water','seedling','light bulb','tree'],{labels:['fresh water','garden','lights off','forest']}),
   cues:[['fresh water','water','water'],['plants a garden','seedling','grow food'],['turns off the lights','light bulb','save electricity'],['cleared a forest','tree','destroy forests']]},
  {say:'Why fresh water matters',speech:'People, animals and plants all need fresh water to live. We drink it, cook with it, wash with it and use it to grow food.',set:S.row(['water','people','corn'],{labels:['drink','people','grow food']}),
   cues:[['need fresh water','water','water'],['grow food','corn','farms']]},
  {say:'Help or harm?',speech:'Planting gardens and turning off lights help. Clearing forests harms. Sort the actions.',set:S.sort(['helps','harms'],[['seedling',0,'plant a garden'],['construction',1,'clear a forest'],['light bulb',0,'lights off'],['trash',1,'litter']]),
   cues:[['help','bin:helps','helps'],['harms','bin:harms','harms','play']]},
  {say:'Future generations',speech:'When we preserve resources, there will be enough for future generations: your children and grandchildren!',set:S.order(['child','woman','grandma']),
   cues:[['future generations','child','future'],['grandchildren','grandma','later','play']]}],
 more:{title:'Did you know?',text:'Canada has about *one fifth* of all the fresh water in the world’s lakes and rivers! The *Great Lakes* alone hold an enormous amount. That is a big reason Canadians must help keep our water clean.',pics:['lake','canada','water','fish'],lead:'A Canada fact!'},
 rounds:[R.q('Which action does *not* save resources?',['clearing a forest for a road','turning off lights','planting a garden'],'clearing a forest for a road'),R.q('Turning off the lights helps…',['save electricity','destroy forests','grow food'],'save electricity',{set:{row:['light bulb'],keep:true}}),
  R.q('Planting a garden helps you…',['grow your own food','waste water','make noise'],'grow your own food'),R.sort('Helps or harms?',['helps','harms'],[['seedling',0,'plant a garden'],['construction',1,'clear a forest'],['light bulb',0,'lights off'],['trash',1,'litter']]),
  R.q('Why is fresh water important?',['people, animals and plants need it','it is pretty','it is salty'],'people, animals and plants need it'),R.q('What is a *resource*?',['something from nature that people use','a toy','a game'],'something from nature that people use'),
  R.q('One way to preserve water is…',['turn off the tap','leave the hose on','take very long baths'],'turn off the tap'),R.q('Which continent has a lot of fresh water?',['North America','Antarctica as liquid water','the Sahara'],'North America'),
  R.q('Why preserve resources?',['so future generations have enough','to win a prize','to make them disappear'],'so future generations have enough'),R.tf('Clearing forests destroys resources.',true),
  R.q('In "Did you know?", Canada has about ___ of the world’s fresh lake and river water.',['one fifth','one hundredth','none'],'one fifth'),R.q('Which is a resource?',['forests','video games','stickers'],'forests')],
 tries:[['Name one resource.','*water*, *trees*, *soil*'],['How can you save electricity?','turn off *lights* and *screens*']]});
})();
